import{_ as d,o as a,c as e,ag as o}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Ustawienia","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station-business/settings.md","filePath":"pl/repair-station-business/settings.md"}'),i={name:"pl/repair-station-business/settings.md"};function c(n,t,r,s,l,z){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="ustawienia" tabindex="-1">Ustawienia <a class="header-anchor" href="#ustawienia" aria-label="Permalink to &quot;Ustawienia&quot;">​</a></h1><p>Każde ustawienie Repair Station Business edytuje się w <code>/nay</code>, na stronie <strong>Repair Station Business</strong> (scope <code>nay_repair_business.config</code>). Zmiany zapisują się w bazie danych i działają od razu dla wszystkich graczy. <code>config.lua</code> zawiera opcjonalne wartości startowe: obowiązują, dopóki ustawienie nie zostanie zmienione w <code>/nay</code>, a <strong>Resetuj</strong> do nich wraca.</p><p>Kolumna <strong>W /nay</strong> to nazwa wyświetlana w panelu. Klucz to nazwa używana przez <code>config.lua</code> i <a href="/pl/nay-lib/api">API HTTP</a>.</p><h2 id="ogolne" tabindex="-1">Ogólne <a class="header-anchor" href="#ogolne" aria-label="Permalink to &quot;Ogólne&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Włączone</td><td><code>Enabled</code></td><td>wł. / wył.</td><td>wł.</td><td>Włącza lub wyłącza funkcje własności. Po wyłączeniu stacje działają jak zwykłe Repair Station. Właściciele nadal mogą wypłacić pieniądze z kasy lub sprzedać stację.</td></tr><tr><td>Stacje na sprzedaż bez właściciela</td><td><code>UnownedMode</code></td><td><code>open</code> lub <code>closed</code></td><td><code>open</code></td><td>Otwarta: gracze nadal mogą tam naprawiać. Zamknięta: stacja odmawia napraw, dopóki ktoś jej nie kupi.</td></tr></tbody></table><h2 id="własnosc" tabindex="-1">Własność <a class="header-anchor" href="#własnosc" aria-label="Permalink to &quot;Własność&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Stacje na sprzedaż</td><td><code>Purchasable</code></td><td>lista, do 64</td><td>brak</td><td>Stacje, które gracze mogą kupić. Użyj panelu administratora, aby zarządzać nimi w grze.</td></tr><tr><td>Stacje na gracza</td><td><code>MaxStationsPerPlayer</code></td><td>liczba, od 1 do 16</td><td>1</td><td>Ile stacji może mieć jeden gracz.</td></tr><tr><td>Konto zakupu</td><td><code>BuyAccount</code></td><td><code>cash</code> lub <code>bank</code></td><td><code>bank</code></td><td>Konto, z którego pobierana jest cena zakupu.</td></tr><tr><td>Odkup (%)</td><td><code>SellBackPercent</code></td><td>liczba, od 0 do 100</td><td>50</td><td>Część ceny zakupu zwracana, gdy właściciel sprzeda lub straci stację.</td></tr><tr><td>Limit nieaktywności (dni)</td><td><code>InactivityDays</code></td><td>liczba, od 0 do 90</td><td>14</td><td>Właściciel, który tak długo nie otworzy tabletu, traci stację i dostaje zwrot. 0 wyłącza ten limit.</td></tr></tbody></table><h2 id="magazyn" tabindex="-1">Magazyn <a class="header-anchor" href="#magazyn" aria-label="Permalink to &quot;Magazyn&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Pojemność magazynu</td><td><code>Capacity</code></td><td>liczba, od 10 do 10000</td><td>100</td><td>Maksymalna liczba części, jaką może pomieścić stacja.</td></tr><tr><td>Części na silnik</td><td><code>PartsEngine</code></td><td>liczba, od 0 do 100</td><td>2</td><td>Części zużywane przez usługę naprawiającą silnik.</td></tr><tr><td>Części na karoserię</td><td><code>PartsBody</code></td><td>liczba, od 0 do 100</td><td>3</td><td>Części zużywane przez usługę naprawiającą karoserię.</td></tr><tr><td>Części na opony</td><td><code>PartsTyres</code></td><td>liczba, od 0 do 100</td><td>1</td><td>Części zużywane przez usługę naprawiającą opony.</td></tr><tr><td>Tryb uzupełniania</td><td><code>RestockMode</code></td><td><code>purchase</code>, <code>items</code> lub <code>both</code></td><td><code>both</code></td><td>Jak właściciele uzupełniają magazyn.</td></tr><tr><td>Cena za część</td><td><code>PartPrice</code></td><td>liczba, od 0 do 100000</td><td>40</td><td>Płatne z konta bankowego właściciela przy zakupie części.</td></tr><tr><td>Przedmiot z częściami</td><td><code>PartItem</code></td><td>tekst, od 1 do 64 znaków</td><td><code>nay_repair_parts</code></td><td>Przedmiot z ekwipunku oddawany w celu uzupełnienia magazynu.</td></tr><tr><td>Części na przedmiot</td><td><code>PartsPerItem</code></td><td>liczba, od 1 do 100</td><td>5</td><td>Liczba części dodawanych do magazynu przez jeden przedmiot.</td></tr><tr><td>Alert niskiego stanu</td><td><code>LowStockThreshold</code></td><td>liczba, od 0 do 10000</td><td>10</td><td>Właściciel dostaje ostrzeżenie, gdy stan magazynu spadnie poniżej tej liczby. 0 wyłącza alert.</td></tr></tbody></table><h2 id="ceny" tabindex="-1">Ceny <a class="header-anchor" href="#ceny" aria-label="Permalink to &quot;Ceny&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Najniższa cena (%)</td><td><code>MinPricePercent</code></td><td>liczba, od 10 do 100</td><td>50</td><td>Najniższa część ceny usługi, jaką może ustawić właściciel.</td></tr><tr><td>Najwyższa cena (%)</td><td><code>MaxPricePercent</code></td><td>liczba, od 100 do 500</td><td>200</td><td>Najwyższa część ceny usługi, jaką może ustawić właściciel.</td></tr><tr><td>Podatek (%)</td><td><code>TaxPercent</code></td><td>liczba, od 0 do 90</td><td>10</td><td>Część każdej płatności za naprawę, która nie trafia do kasy.</td></tr></tbody></table><h2 id="mapa" tabindex="-1">Mapa <a class="header-anchor" href="#mapa" aria-label="Permalink to &quot;Mapa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Kolor blipa własnej stacji</td><td><code>OwnedBlipColor</code></td><td>liczba, od 0 do 85</td><td>2</td><td>Kolor blipa stacji, które posiadasz, na twojej mapie.</td></tr><tr><td>Kolor blipa stacji na sprzedaż</td><td><code>ForSaleBlipColor</code></td><td>liczba, od 0 do 85</td><td>5</td><td>Kolor blipa stacji na sprzedaż.</td></tr></tbody></table><p>Wpisy <strong>Stacji na sprzedaż</strong>:</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th></tr></thead><tbody><tr><td>Identyfikator stacji</td><td><code>StationId</code></td><td>8 znaków (0 do 9, a do f), jak w edytorze Repair Station.</td></tr><tr><td>Cena</td><td><code>Price</code></td><td>liczba, od 0 do 100000000</td></tr></tbody></table><p>Procenty właściciela (<code>MinPricePercent</code>, <code>MaxPricePercent</code>) dotyczą ceny każdej usługi, przed zniżkami dla zawodów. Podatek (<code>TaxPercent</code>) jest pobierany z każdej płatności za naprawę, zanim trafi do kasy.</p>',16)])])}const y=d(i,[["render",c]]);export{h as __pageData,y as default};
